
const mongoose = require("mongoose");

const callEventSchema = new mongoose.Schema(
  {
    deviceId: {
      type: String,
      required: true,
      trim: true,
      index: true,
    },
    deviceName: {
      type: String,
      required: true,
      trim: true,
    },
    // Stable ID generated by the Android app for deduplication.
    eventKey: {
      type: String,
      required: true,
      trim: true,
    },
    type: {
      type: String,
      enum: ["incoming", "missed", "outgoing", "rejected", "unknown"],
      required: true,
    },
    phoneNumber: {
      type: String,
      default: "",
      trim: true,
      maxlength: 50,
    },
    contactName: {
      type: String,
      default: "",
      trim: true,
      maxlength: 200,
    },
    startedAt: {
      type: Date,
      required: true,
    },
    durationSeconds: {
      type: Number,
      default: 0,
      min: 0,
    },
    source: {
      type: String,
      enum: ["notification", "call_log", "other"],
      default: "notification",
    },
  },
  { timestamps: true }
);

callEventSchema.index(
  { deviceId: 1, eventKey: 1 },
  { unique: true }
);

callEventSchema.index({ deviceId: 1, startedAt: -1 });
callEventSchema.index({ deviceId: 1, type: 1, startedAt: -1 });

module.exports = mongoose.model("CallEvent", callEventSchema);
